-- 研究池：玻色量子 高管团队 + 技术动态修复（2026-11-28）
-- 1) 新增 executives（4 人核心团队），补 team 简介与 execChanges 人事项
-- 2) tech 原为纯字符串数组，详情页按 {date,title,kind} 渲染导致空行，改为带日期的真实事件
-- 仅合并这四个键，不整包覆盖，避免抹掉后续人工修订
UPDATE public.research_companies
SET data = data
  || jsonb_build_object(
       'executives', '[{"bio": "清华大学基础科学班（数理基础科学）本硕 → 斯坦福大学电子工程博士，师从清华大学龙桂鲁教授与相干伊辛机（CIM）提出者、量子光学泰斗山本喜久（Yoshihisa Yamamoto），为该方向全球首位博士。现任董事长兼 CEO、法定代表人、实际控制人，兼任粤港澳大湾区（广东）量子科学中心 PI 研究员，主导技术路线、战略与融资。辅导备案口径持股 21.51%（工商登记 22.94%，差异源于统计时点与是否穿透持股平台）。", "name": "文凯", "role": "management", "title": "创始人、董事长兼 CEO", "shares": "21.51%（辅导备案口径）"}, {"bio": "天津大学精密仪器学院本科 → 中国科学院国家空间科学中心硕士，现于北京师范大学人工智能学院攻读博士。曾长期任职航天系统，参与并负责多艘载人飞船与中国空间站精密仪器分系统的总体软硬件设计。现任副董事长兼 COO，负责商业化落地、政企与客户关系、产业生态及知识产权，带领团队获授权发明专利 40 余项；兼任信通院量子计算产业知识产权联盟副理事长，北航、天津大学、东南大学校外导师，中国移动、中电科量子计算外部专家。", "name": "马寅", "role": "management", "title": "创始人、副董事长兼 COO", "shares": "14.95%（辅导备案口径）"}, {"bio": "清华大学电子工程系本科 → 斯坦福大学电子工程博士，研究方向为高性能计算与新型计算范式，博士期间参与研发世界首台碳纳米管计算机，成果登上《Nature》封面。曾任麦肯锡咨询顾问、饿了么商业分析副总裁、百度外卖 CEO、阿里巴巴集团高管。2020 年应文凯之邀联合创办玻色量子，负责光路系统、整机工程化与量产交付，是《Light: Science & Applications》CIM 论文共同第一作者兼共同通讯作者。其价值不在光学出身，而在把原型机做成可交付整机的工程与组织能力。", "name": "魏海", "role": "management", "title": "联合创始人、CTO、董事", "tenure": "2020.11 至今（董事 2023.02 起）"}, {"bio": "清华大学博士，北京师范大学人工智能学院教授、北京量子信息科学研究院研究员，从事量子计算、量子机器学习与微纳光学研究，发表 SCI 论文 150 余篇、被引 5,000 余次，连续五年入选 Elsevier 中国高被引学者与斯坦福全球 Top 2% 科学家榜单；主持国家自然科学基金优青及重点项目，获国家自然科学二等奖，任中国通信学会量子通信专委会副主任。以首席科学家身份与公司联合研究，为 CIM 论文共同通讯作者，非全职雇员。", "name": "王川", "role": "management", "title": "首席科学家（外聘）"}]'::jsonb,
       'team', '"四人核心：创始人兼 CEO 文凯（清华基科班 → 斯坦福，师从 CIM 提出者山本喜久，该方向全球首位博士）、创始人兼 COO 马寅（天大精仪 → 中科院空间中心 → 北师大博士，航天型号背景）、CTO 魏海（清华电子 → 斯坦福，首台碳纳米管计算机 Nature 封面作者，前百度外卖 CEO / 阿里高管）、首席科学家王川（北师大教授、北京量子院研究员，外聘）。团队 200+ 人、硕博占比约 65%；四位均无中科院或院士体系直接持股，属市场化海归团队，与本源量子（郭光灿系）、国仪量子形成对照。"'::jsonb,
       'execChanges', '[{"date": "2026-07", "event": "A 股 IPO 辅导备案获北京证监局受理（国泰海通），国内第二家启动上市的量子计算公司"}, {"date": "2023-02", "event": "魏海出任公司董事，负责整机工程化与量产"}, {"date": "2020-11", "event": "文凯、马寅、魏海联合创立，文凯任董事长兼 CEO、马寅任 COO、魏海任 CTO"}]'::jsonb,
       'tech', '[{"date": "2026-05", "kind": "产品", "title": "发布「驭量·山海1000」：标准 1,000 比特 / 精准 550 比特 / 超频 3,000 比特，支持多机并联"}, {"date": "2026-05", "kind": "产品", "title": "发布首款通用光量子芯片，薄膜铌酸锂电光调制，单比特门保真度 >98%"}, {"date": "2026-01", "kind": "论文", "title": "CIM 成果登上《Light: Science & Applications》：100 顶点基准最优解成功率 55%，求解 464 微秒"}, {"date": "2025-12", "kind": "量产", "title": "深圳南山建成国内首个规模化专用量子计算机制造工厂，具备整机批量交付能力"}, {"date": "2025-04", "kind": "产品", "title": "1,000 比特专用量子计算机上线云服务，DOPO + PPLN 非线性晶体，室温运行"}]'::jsonb
     ),
    updated_at = now()
WHERE name = '玻色量子';
